import json,os,subprocess,shutil
from pathlib import Path
res={"pm2_binary":shutil.which("pm2"),"global_home_exists":Path("/root/.pm2").is_dir(),"new_homes":{}}
for p in ("/srv/projects/telegram-robot-leads/.pm2","/srv/projects/iptvpn-bot/.pm2"):
 r=Path(p);res["new_homes"][p]={"exists":r.exists() or r.is_symlink(),"root_exists":r.parent.is_dir()}
dump=Path("/root/.pm2/dump.pm2")
if dump.is_file():
 try:
  apps=json.loads(dump.read_text())
  res["saved_apps"]=[{"name":a.get("name"),"cwd":(a.get("pm2_env") or {}).get("pm_cwd",a.get("pm_cwd")),"exec":(a.get("pm2_env") or {}).get("pm_exec_path",a.get("pm_exec_path"))} for a in apps if isinstance(a,dict)]
 except Exception:res["saved_apps"]="unreadable"
try:
 p=subprocess.run(["pm2","jlist"],env=dict(os.environ,PM2_HOME="/root/.pm2"),capture_output=True,text=True,timeout=12)
 res["jlist_exit"]=p.returncode
 if p.returncode==0:
  apps=json.loads(p.stdout)
  res["live_apps"]=[{"name":a.get("name"),"pid":a.get("pid"),"status":(a.get("pm2_env") or {}).get("status"),"cwd":(a.get("pm2_env") or {}).get("pm_cwd"),"exec":(a.get("pm2_env") or {}).get("pm_exec_path")} for a in apps]
except Exception as e:res["jlist_error"]=type(e).__name__
try:
 r=subprocess.run(["systemctl","show","pm2-root","--property=ActiveState,SubState,ExecStart,ExecStop,User"],capture_output=True,text=True,timeout=8)
 res["pm2_service"]=[v.split("=",1)[0]+":configured" for v in r.stdout.splitlines() if "=" in v and v.split("=",1)[1]]
except Exception:pass
print(json.dumps(res,sort_keys=True))
